 static String rewrite(String input){String q=CreationRequest.normalize(input).replaceFirst("^no[, ]+","");q=q.replaceAll("\\b(el|la) que entra\\b","$1 que entro");Matcher m=Pattern.compile("(?:hace que )?(.+?) (?:tiene que ser|deberia ser|debe ser) (azul|rojo|roja|verde|amarillo|amarilla|violeta|rosa|blanco|blanca|negro|negra)").matcher(q);if(m.matches())return "pone a "+m.group(1)+" "+m.group(2);if(!q.contains(" dice ")&&q.matches("(?s).*(?:el|la) que (?:entro|habla|baila|salta).*"))return q;return input;}
 static void resetConversation(Context c){RequestDialogue.clear(c);prefs(c).edit().remove("lastMessage").remove("lastCommand").remove("lastReply").remove("lastMode").remove("lastEffect").remove("lastLesson").remove("repair").apply();}
