 static String teach(Context c,String message)throws Exception{Matcher m=Pattern.compile("(?isu)^cuando diga [\"“](.+?)[\"”] quiero decir [\"“](.+?)[\"”]$").matcher(message.trim());if(!m.matches())return null;String phrase=ChatLanguage.normalize(m.group(1)),command=m.group(2).trim();if(phrase.length()<3||phrase.length()>80||command.length()>400||!CreationRequest.normalize(command).matches("(?s)^(?:crea|creame|agrega|pone|cambia|continua|hace|voz de|quita) .*")||phrase.matches("(?s)^(?:aplica|deshacer|rehacer|borra|olvida|mis frases|cuando diga|aprende).*"))return "Usá una frase de tres a ochenta caracteres y una orden de escena de hasta cuatrocientos. No se pueden reemplazar controles de borrado, historial o planes.";JSONArray a=aliases(c),next=new JSONArray();for(int i=0;i<a.length();i++)if(!a.getJSONObject(i).getString("phrase").equals(phrase))next.put(a.getJSONObject(i));if(next.length()>=32)return "Llegamos a treinta y dos frases. Borrá una con ‘olvida la frase …’.";next.put(new JSONObject().put("phrase",phrase).put("command",command));if(!prefs(c).edit().putString("aliases",next.toString()).commit())throw new java.io.IOException("No pude guardar la frase.");return "Guardé tu equivalencia local: «"+phrase+"» → «"+command+"». No ejecuté la orden todavía. Es una regla que vos enseñaste, no entrenamiento automático del modelo.";}
 static String explain(Context c){SharedPreferences p=prefs(c);String request=p.getString("lastMessage",""),command=p.getString("lastCommand",""),mode=p.getString("lastMode","");if(request.isEmpty())return "Todavía no hay un pedido registrado por este núcleo.";return "Tu pedido fue: "+request+"\nLo interpreté como: "+command+"\nRuta utilizada: "+mode+".\n"+p.getString("lastEffect","No registré un cambio de escena.")+"\nEsto describe operaciones y resultados guardados; no es una explicación de un razonamiento general que el modelo no tiene.";}
 static void record(Context c,String message,String command,BananaEngine.Result out,SceneDraft before)throws Exception{PlannerExperience.record(c,command,out);String effect=out.changed&&out.scene!=null?TaskReceipt.describe(before,out.scene,new String[]{command}):"No apliqué cambios a la escena en esa respuesta.";if(!prefs(c).edit().putString("lastMessage",message).putString("lastCommand",command).putString("lastReply",out.text.substring(0,Math.min(6000,out.text.length()))).putString("lastMode",out.mode).putString("lastEffect",effect).commit())throw new java.io.IOException("El resultado se produjo, pero no pude guardar su registro conversacional.");}
