  SharedPreferences p=prefs(c);String q=ChatLanguage.normalize(message),style=p.getString("style","normal");
  if(q.matches("responde breve|respuestas breves|modo breve|responde detallado|respuestas detalladas|modo detallado|modo normal")){String s=q.contains("breve")?"breve":q.contains("detallad")?"detallado":"normal";p.edit().putString("style",s).apply();return say(c,"Elegí el estilo "+s+" para las explicaciones locales. Los límites y las fuentes se siguen mostrando.","nucleo");}
