  if(q.equals("estado del nucleo"))return say(c,"Núcleo móvil 1 · Android, sin PC.\nMemoria de trabajo: "+(p.getString("lastMessage","").isEmpty()?"sin pedido registrado":p.getString("lastMessage",""))+"\nEstilo: "+style+"\nFrases enseñadas: "+aliases(c).length()+" / 32\nPlan pendiente: "+MobilePlan.stored(c).size()+" pasos.\n24 lecciones locales con selector neuronal propio. Chat3.4 sigue como generador experimental; este núcleo no equivale a una inteligencia general.","nucleo");
