  if(q.startsWith("reformula mi pregunta ")){String corrected=message.substring(message.indexOf(':')>=0?message.indexOf(':')+1:"reformula mi pregunta ".length()).trim();if(corrected.length()<3)return say(c,"Escribí la pregunta completa después de los dos puntos.","reparacion");message=corrected;q=ChatLanguage.normalize(message);p.edit().putBoolean("repair",false).apply();}
  String taught=teach(c,message);if(taught!=null)return say(c,taught,"aprendizaje_local");
  if(q.equals("mis frases")){StringBuilder b=new StringBuilder("Frases que vos enseñaste:");JSONArray a=aliases(c);for(int i=0;i<a.length();i++)b.append("\n").append(a.getJSONObject(i).getString("phrase")).append(" → ").append(a.getJSONObject(i).getString("command"));return say(c,b.toString(),"aprendizaje_local");}
  if(q.startsWith("olvida la frase ")){String target=q.substring("olvida la frase ".length());JSONArray a=aliases(c),next=new JSONArray();for(int i=0;i<a.length();i++)if(!a.getJSONObject(i).getString("phrase").equals(target))next.put(a.getJSONObject(i));if(!p.edit().putString("aliases",next.toString()).commit())throw new java.io.IOException("No pude borrar la frase");return say(c,next.length()<a.length()?"Borré esa equivalencia.":"Esa equivalencia no estaba guardada.","aprendizaje_local");}
  if(q.startsWith("anota esta correccion ")){String correction=message.substring(message.indexOf(':')>=0?message.indexOf(':')+1:"anota esta correccion ".length()).trim();if(correction.length()<3||correction.length()>400)return say(c,"La corrección admite de tres a cuatrocientos caracteres.","aprendizaje_local");JSONArray feedback=new JSONArray(p.getString("feedback","[]")),next=new JSONArray();for(int i=Math.max(0,feedback.length()-49);i<feedback.length();i++)next.put(feedback.getJSONObject(i));next.put(new JSONObject().put("question",p.getString("lastMessage","")).put("answer",p.getString("lastReply","")).put("correction",correction).put("source","user").put("saved",System.currentTimeMillis()));if(!p.edit().putString("feedback",next.toString()).commit())throw new java.io.IOException("No pude guardar la corrección.");return say(c,"Guardé tu corrección como aporte del usuario. No reemplaza una fuente comprobada ni cambia automáticamente los pesos.","aprendizaje_local");}
  if(q.equals("mis correcciones")){JSONArray a=new JSONArray(p.getString("feedback","[]"));StringBuilder b=new StringBuilder("Correcciones que vos aportaste:");for(int i=0;i<a.length();i++)b.append("\n").append(i+1).append(". ").append(a.getJSONObject(i).optString("correction"));return say(c,b.toString(),"aprendizaje_local");}
  if(q.equals("borra mis correcciones")){p.edit().remove("feedback").apply();return say(c,"Borré el registro de correcciones del núcleo.","aprendizaje_local");}
