  Matcher edit=Pattern.compile("(?isu)^(?:corrige|corregi|corregí|cambia) paso ([0-9]{1,2})\\s*:\\s*(.+)$").matcher(message.trim());if(edit.matches()){List<String> rows=MobilePlan.stored(c);int at=Integer.parseInt(edit.group(1))-1;if(at<0||at>=rows.size())return say(c,"Ese paso no existe en el plan pendiente.","plan");if(!p.getString("planSnapshot","").equals(MobilePlan.snapshot(c)))return say(c,"El proyecto cambió; prepará el plan otra vez antes de corregirlo.","plan");rows.set(at,edit.group(2).trim());MobilePlan.save(c,rows,p.getString("planSnapshot",""));return say(c,MobilePlan.describe(rows)+"\nNo lo apliqué todavía.","plan");}
  String command=alias(c,message);boolean planRequested=q.startsWith("planea ")||q.startsWith("prepara un plan ");if(planRequested)command=message.substring(message.indexOf(':')>=0?message.indexOf(':')+1:q.startsWith("planea ")?7:"prepara un plan ".length()).trim();
  List<String> steps=MobilePlan.split(command);if(planRequested){MobilePlan.save(c,steps,MobilePlan.snapshot(c));return say(c,MobilePlan.describe(steps)+"\nPodés corregir un paso o decir ‘aplica el plan’.","plan");}
